const videoElements = document.querySelectorAll('ytd-rich-grid-media, ytd-grid-video-renderer');
const topVideos = Array.from(videoElements).slice(0, 10).map(el => {
  const titleEl = el.querySelector('#video-title, .yt-core-attributed-string--link-inherit-color');
  const linkEl = el.querySelector('#video-title, a#video-title-link');
  const viewsEl = el.querySelector('#metadata-line span, .inline-metadata-item');
  const dateEl = el.querySelector('#metadata-line span:last-child, .inline-metadata-item:last-child');
  const thumbnailEl = el.querySelector('img.yt-core-image--fill-parent-height');
  const durationEl = el.querySelector('.badge-shape-wiz__text, .ytd-thumbnail-overlay-time-status-renderer');
  return {
    title: titleEl?.innerText?.trim(),
    url: linkEl?.href,
    views: viewsEl?.innerText?.trim(),
    uploadDate: dateEl?.innerText?.trim(),
    thumbnail: thumbnailEl?.src,
    duration: durationEl?.innerText?.trim()
  };
}).filter(x => x.title && x.title.length > 5);
return topVideos;

const results = [];
const videos = window.economist_top_videos || [];
for (let i = 0; i < Math.min(videos.length, 5); i++) {
  const video = videos[i];
  if (!video.url) continue;
  try {
    const response = await fetch(video.url);
    const html = await response.text();
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    const descMeta = doc.querySelector('meta[name="description"]');
    const description = descMeta?.getAttribute('content') || '';

    const keywordsMeta = doc.querySelector('meta[name="keywords"]');
    const tags = keywordsMeta?.getAttribute('content')?.split(',').map(t => t.trim()) || [];

    const likeEl = doc.querySelector('#segmented-like-button, .yt-spec-button-shape-next--tonal');
    const likes = likeEl?.getAttribute('aria-label') || '';

    const videoIdMatch = video.url?.match(/[?&]v=([^&]+)/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    results.push({
      title: video.title,
      url: video.url,
      videoId: videoId,
      views: video.views,
      uploadDate: video.uploadDate,
      duration: video.duration,
      description: description.substring(0, 500),
      tags: tags,
      likes: likes
    });
  } catch (e) {
    results.push({
      title: video.title,
      url: video.url,
      error: e.message
    });
  }
}
return results;

